 // hist[b] = number of i < n with (in[i] & 255) == b for b < 256. Neither out nor
 // hist is zeroed by the caller. n is any size from 0 to 20'000'000; the sums
 // never overflow int64.
+//
+// Strategy: 8 private uint32_t sub-histograms (element i -> sub-histogram i & 7)
+// so consecutive hot-bin increments don't form one long store-to-load dependency
+// chain. The sub-histograms are merged into hist (uint64_t) at the end. The
+// prefix sum is kept in a scalar register.
+
+#if defined(__ARM_NEON)
+#include <arm_neon.h>
+#endif
+
 extern "C" void scan_and_histogram(const int64_t* in, int64_t* out, size_t n, uint64_t* hist) {
-    for (int b = 0; b < 256; ++b) hist[b] = 0;
+    if (n == 0) {
+        for (int b = 0; b < 256; ++b) hist[b] = 0;
+        return;
+    }
+
+    constexpr int NSUB = 4;
+    uint32_t hsub[NSUB][256];
+    for (int s = 0; s < NSUB; ++s)
+        for (int b = 0; b < 256; ++b)
+            hsub[s][b] = 0;
+
     int64_t sum = 0;
-    for (size_t i = 0; i < n; ++i) {
+    size_t i = 0;
+
+    size_t n4 = (n & ~(size_t)3);
+    for (; i < n4; i += 4) {
+        int64_t v0 = in[i];     sum += v0; out[i + 0] = sum; hsub[0][v0 & 255]++;
+        int64_t v1 = in[i + 1]; sum += v1; out[i + 1] = sum; hsub[1][v1 & 255]++;
+        int64_t v2 = in[i + 2]; sum += v2; out[i + 2] = sum; hsub[2][v2 & 255]++;
+        int64_t v3 = in[i + 3]; sum += v3; out[i + 3] = sum; hsub[3][v3 & 255]++;
+    }
+
+    for (; i < n; ++i) {
         sum += in[i];
         out[i] = sum;
-        hist[in[i] & 255]++;
+        hsub[i & 3][in[i] & 255]++;
+    }
+
+    for (int b = 0; b < 256; ++b) {
+        uint64_t total = 0;
+        for (int s = 0; s < NSUB; ++s) total += hsub[s][b];
+        hist[b] = total;
     }
 }
